{"content": "#!/usr/bin/env python3
"""WebShaper-style formal multi-hop question synthesis over kb.py (Pipeline C, design doc 4.1).

Formal expressions are nested JSON-serializable lists evaluated as set operations:

  ["E", name]                      singleton set {name}
  ["R", rel, sub, out_type]        forward relation image  {y : x in sub, x --rel--> y}
  ["RI", rel, sub, out_type]       inverse relation image  {x : y in sub, x --rel--> y}
  ["F", sub, attr, op, value]      attribute filter, op in eq|ne|gt|ge|lt|le
  ["NE", sub, name]                set minus a named entity

Generation (WebShaper "confusion-ization" idea): from a seed entity, expand hop by hop
(2-6 hops) mixing forward/inverse relation steps with a 1..10 sized frontier, then
constrain the final set with attribute filters / exclusions until the evaluated answer
set is EXACTLY one entity -> the unique answer is guaranteed by construction and
re-checkable with `verify_task`. Difficulty is controlled by:
  --hops-min/--hops-max   hop count of the main entity chain
  --confounders N         number of same-type, attribute-sharing "confusable" entities
                          recorded in meta (hard negatives for RL / answer checking)

The teacher is only used to rewrite the template NL question into fluent English
(`rewrite_with_teacher`); it is skipped with --no-teacher and the template text is used.

Usage:
  python3 pipelines/deep_search/task_gen.py --num 10 --hops-min 2 --hops-max 6 --self-check
  python3 pipelines/deep_search/task_gen.py --num 4 --hops-min 3 --hops-max 3 --confounders 3 --out tasks.jsonl
"""
from __future__ import annotations

import argparse
import json
import random
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[2]))

from pipelines.common import teacher_client  # noqa: E402  (no network at import time)
from pipelines.deep_search import kb  # noqa: E402

# inverse relations usable during generation (keeps frontier types homogeneous)
INV_OK = ["born_in", "studied_at", "worked_at", "won", "wrote", "directed",
          "headquartered_in", "flows_through", "capital_of"]

FWD_NP = {
    "born_in": "the city where {x} was born",
    "located_in": "the {tt} in which {x} is located",
    "capital_of": "the country whose capital is {x}",
    "flows_through": "a city through which {x} flows",
    "headquartered_in": "the city where {x} is headquartered",
    "studied_at": "the university where {x} studied",
    "worked_at": "the organization where {x} worked",
    "won": "the award that {x} won",
    "wrote": "the book that {x} wrote",
    "directed": "the film that {x} directed",
}
# inverse noun-phrase bodies; plural ones get "one of the ..." at question root
INV_NP = {
    "born_in": ("people born in {x}", True),
    "studied_at": ("people who studied at {x}", True),
    "worked_at": ("people who worked at {x}", True),
    "won": ("people who won {x}", True),
    "wrote": ("the author of {x}", False),
    "directed": ("the director of {x}", False),
    "headquartered_in": ("companies headquartered in {x}", True),
    "flows_through": ("rivers that flow through {x}", True),
    "capital_of": ("the capital city of {x}", False),
}

ATTR_PHRASES = {
    "birth_year": {"eq": "was born in {v}", "ne": "was not born in {v}",
                   "gt": "was born after {v}", "lt": "was born before {v}"},
    "nationality": {"eq": "is {v}", "ne": "is not {v}"},
    "occupation": {"eq": "works as a {v}"},
    "published_year": {"eq": "was published in {v}", "gt": "was published after {v}",
                       "lt": "was published before {v}"},
    "release_year": {"eq": "was released in {v}", "gt": "was released after {v}",
                     "lt": "was released before {v}"},
    "founded_year": {"eq": "was founded in {v}", "gt": "was founded after {v}",
                     "lt": "was founded before {v}"},
    "established_year": {"eq": "was established in {v}", "gt": "was established after {v}",
                         "lt": "was established before {v}"},
    "population_millions": {"eq": "has a population of {v} million",
                            "gt": "has a population of more than {v} million",
                            "lt": "has a population of less than {v} million"},
    "official_language": {"eq": "has {v} as an official language"},
    "continent": {"eq": "is located in {v}"},
    "genre": {"eq": "belongs to the {v} genre"},
    "length_km": {"gt": "is longer than {v} km", "lt": "is shorter than {v} km"},
}
_GENERIC_PHRASES = {"eq": "has {k} equal to {v}", "ne": "has {k} different from {v}",
                    "gt": "has {k} greater than {v}", "lt": "has {k} less than {v}",
                    "ge": "has {k} of at least {v}", "le": "has {k} of at most {v}"}


# ----------------------------------------------------------------- evaluation

def _cmp(x, op: str, v) -> bool:
    if x is None:
        return False
    if op == "eq":
        return x == v
    if op == "ne":
        return x != v
    if not isinstance(x, (int, float)) or isinstance(x, bool):
        return False
    return {"gt": x > v, "ge": x >= v, "lt": x < v, "le": x <= v}[op]


def evaluate(expr) -> set[str]:
    op = expr[0]
    if op == "E":
        return {expr[1]}
    if op == "R":
        out: set[str] = set()
        for e in evaluate(expr[2]):
            out.update(kb.rels_of(e).get(expr[1], []))
        return out
    if op == "RI":
        out = set()
        for e in evaluate(expr[2]):
            out.update(kb.inv_rels_of(e).get(expr[1], []))
        return out
    if op == "F":
        return {e for e in evaluate(expr[1]) if _cmp(kb.attrs_of(e).get(expr[2]), expr[3], expr[4])}
    if op == "NE":
        return evaluate(expr[1]) - {expr[2]}
    raise ValueError(f"unknown expr op: {op!r}")


def verify_task(task: dict) -> tuple[bool, list[str]]:
    """Re-evaluate the formal expression; ok iff the answer set is exactly {answer}."""
    try:
        s = evaluate(task["expression"])
    except Exception:  # noqa: BLE001
        return False, []
    return s == {task["answer"]}, sorted(s)


# ----------------------------------------------------------------- NL render

def np_of(chain) -> str:
    op = chain[0]
    if op == "E":
        return chain[1]
    if op == "R":
        return FWD_NP[chain[1]].format(x=np_of(chain[2]), tt=chain[3])
    if op == "RI":
        return INV_NP[chain[1]][0].format(x=np_of(chain[2]))
    raise ValueError(f"not a chain node: {op!r}")


def _unwrap(expr):
    """Split stacked F/NE constraint nodes from the underlying relation chain."""
    conds = []
    while expr[0] in ("F", "NE"):
        if expr[0] == "F":
            conds.append(("F", expr[2], expr[3], expr[4]))
        else:
            conds.append(("NE", expr[2]))
        expr = expr[1]
    conds.reverse()
    return expr, conds


def _attr_phrase(attr: str, op: str, v) -> str:
    tmpl = ATTR_PHRASES.get(attr, {}).get(op) or _GENERIC_PHRASES[op]
    return tmpl.format(k=attr.replace("_", " "), v=v)


def render_question(expr, answer_type: str) -> str:
    chain, conds = _unwrap(expr)
    lines = [f"Which {answer_type} satisfies ALL of the following conditions?"]
    if chain[0] == "RI" and INV_NP[chain[1]][1]:
        lines.append(f"- It is one of the {np_of(chain)}.")
    else:
        lines.append(f"- It is {np_of(chain)}.")
    for c in conds:
        if c[0] == "F":
            lines.append(f"- It {_attr_phrase(c[1], c[2], c[3])}.")
        else:
            lines.append(f"- It is not {c[1]}.")
    lines.append("Answer with the exact name only.")
    return "\n".join(lines)


# ----------------------------------------------------------------- generation

def _candidates(cur: set[str]) -> list[tuple[str, str, set[str], str]]:
    """All one-hop moves (kind, rel, next_set, out_type) from the frontier."""
    fwd: dict[str, set[str]] = {}
    inv: dict[str, set[str]] = {}
    for e in cur:
        for rel, tgts in kb.rels_of(e).items():
            fwd.setdefault(rel, set()).update(tgts)
        for rel, srcs in kb.inv_rels_of(e).items():
            if rel in INV_OK:
                inv.setdefault(rel, set()).update(srcs)
    out = []
    for rel, ns in fwd.items():
        out.append(("R", rel, ns, kb.type_of(next(iter(ns)))))
    for rel, ns in inv.items():
        out.append(("RI", rel, ns, kb.type_of(next(iter(ns)))))
    return out


def _has_continuation(ns: set[str]) -> bool:
    return any(kb.rels_of(e) or any(r in INV_OK for r in kb.inv_rels_of(e)) for e in ns)


def _constrain(expr, S: set[str], answer: str, rng: random.Random):
    """Add attribute filters / exclusions until the set is exactly {answer}."""
    others = S - {answer}
    attrs = kb.attrs_of(answer)
    keys = list(attrs)
    rng.shuffle(keys)
    # 1) single attribute equality
    for k in keys:
        v = attrs[k]
        if all(kb.attrs_of(o).get(k) != v for o in others):
            return ["F", expr, k, "eq", v]
    # 2) numeric isolation by a threshold
    for k in keys:
        v = attrs[k]
        if not isinstance(v, (int, float)) or isinstance(v, bool):
            continue
        oth = [kb.attrs_of(o).get(k) for o in others]
        if not all(isinstance(x, type(v)) for x in oth):
            continue
        if all(x > v for x in oth):
            return ["F", expr, k, "lt", min(oth)]
        if all(x < v for x in oth):
            return ["F", expr, k, "gt", max(oth)]
    # 3) pair of attribute equalities
    for i, k1 in enumerate(keys):
        for k2 in keys[i + 1:]:
            e2 = ["F", ["F", expr, k1, "eq", attrs[k1]], k2, "eq", attrs[k2]]
            if evaluate(e2) == {answer}:
                return e2
    # 4) explicit exclusions (only when the residual set is tiny)
    if 1 <= len(others) <= 2:
        e = expr
        for o in sorted(others):
            e = ["NE", e, o]
        return e
    return None


def find_confounders(answer: str, n: int) -> list[str]:
    """Same-type entities sharing >= 1 attribute value with the answer (hard negatives)."""
    a = kb.ENTITIES[answer]
    cands = []
    for e, d in kb.ENTITIES.items():
        if e == answer or d["type"] != a["type"]:
            continue
        shared = sum(1 for k in set(a["attrs"]) & set(d["attrs"])
                     if a["attrs"][k] == d["attrs"][k])
        cands.append((shared, e))
    cands.sort(key=lambda x: (-x[0], x[1]))
    return [e for _s, e in cands[:n]]


def _try_generate(rng: random.Random, hops: int, n_conf: int) -> dict | None:
    seeds = [e for e in kb.all_entities()
             if kb.rels_of(e) or any(r in INV_OK for r in kb.inv_rels_of(e))]
    seed = rng.choice(seeds)
    expr = ["E", seed]
    cur = {seed}
    used_ri = False
    for step in range(hops):
        cands = [(k, r, ns, ot) for k, r, ns, ot in _candidates(cur)
                 if 1 <= len(ns) <= 10 and (step == hops - 1 or _has_continuation(ns))]
        if not cands:
            return None
        ri = [c for c in cands if c[0] == "RI"]
        if hops >= 3 and not used_ri and step == hops - 1 and ri:
            cands = ri
        elif ri and rng.random() < 0.55:
            cands = ri
        kind, rel, ns, ot = rng.choice(cands)
        expr = [kind, rel, expr, ot]
        cur = ns
        used_ri = used_ri or kind == "RI"
    if hops >= 3 and not used_ri:
        return None
    answer_type = kb.type_of(next(iter(cur)))
    if len(cur) == 1:
        answer = next(iter(cur))
        final = expr
    else:
        answer = rng.choice(sorted(cur))
        final = _constrain(expr, cur, answer, rng)
        if final is None:
            return None
    if evaluate(final) != {answer}:
        return None
    return {"hops": hops, "seed": seed, "expression": final,
            "question": render_question(final, answer_type),
            "answer": answer, "answer_type": answer_type,
            "confounders": find_confounders(answer, n_conf),
            "difficulty": {"hops": hops, "confounders": n_conf}}


def generate_task(rng: random.Random, hops: int, n_confounders: int = 2,
                  max_tries: int = 400) -> dict:
    for _ in range(max_tries):
        t = _try_generate(rng, hops, n_confounders)
        if t is not None:
            return t
    raise RuntimeError(f"could not generate a unique-answer task with hops={hops}")


def rewrite_with_teacher(task: dict) -> str:
    """Rewrite the template question into fluent English via the teacher.

    Falls back to the template question on any failure (e.g. no teacher service)."""
    prompt = (
        "Rewrite the following formally-specified multi-hop question into one fluent, "
        "natural English question. Keep every condition, do not add or drop constraints, "
        "and do not reveal the answer. Output only the rewritten question.\n\n"
        f"Formal expression: {json.dumps(task['expression'], ensure_ascii=False)}\n\n"
        f"Template question:\n{task['question']}")
    try:
        text = teacher_client.chat([{"role": "user", "content": prompt}], max_tokens=1024)[0]
        text = text.strip()
        return text if text else task["question"]
    except Exception:  # noqa: BLE001
        return task["question"]


def main() -> None:
    ap = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    ap.add_argument("--num", type=int, default=10)
    ap.add_argument("--hops-min", type=int, default=2)
    ap.add_argument("--hops-max", type=int, default=6)
    ap.add_argument("--confounders", type=int, default=2)
    ap.add_argument("--seed", type=int, default=0)
    ap.add_argument("--no-teacher", action="store_true",
                    help="skip the teacher NL rewrite (template question is used)")
    ap.add_argument("--self-check", action="store_true",
                    help="re-evaluate each expression and verify the answer is unique")
    ap.add_argument("--out", help="optional JSONL dump of generated tasks")
    args = ap.parse_args()

    errs = kb.validate_kb()
    if errs:
        raise SystemExit(f"KB inconsistent: {errs[:5]}")

    rng = random.Random(args.seed)
    span = args.hops_max - args.hops_min + 1
    tasks, failures = [], 0
    for i in range(args.num):
        hops = args.hops_min + (i % span)
        task = generate_task(rng, hops, args.confounders)
        task["id"] = f"task-{i + 1:04d}"
        if not args.no_teacher:
            task["question"] = rewrite_with_teacher(task)
        line = (f"[{task['id']}] hops={hops} answer={task['answer']!r} "
                f"type={task['answer_type']} confounders={len(task['confounders'])}")
        if args.self_check:
            ok, solved = verify_task(task)
            line += f" self_check={'OK' if ok else 'FAIL'}"
            if not ok:
                failures += 1
                line += f" (evaluated={solved})"
        print(line)
        tasks.append(task)
    if args.out:
        with open(args.out, "w", encoding="utf-8") as f:
            for t in tasks:
                f.write(json.dumps(t, ensure_ascii=False) + "\n")
        print(f"wrote {len(tasks)} tasks to {args.out}")
    if args.self_check:
        print(f"self-check: {len(tasks) - failures}/{len(tasks)} unique & evaluable")
        if failures:
            sys.exit(1)


if __name__ == "__main__":
    main()
