{"content": "#!/usr/bin/env python3
"""BrowseComp-style deep-search harness skeleton (Pipeline C, design doc section 4.2).

Components:
  Tool protocol      abstract `Tool` (name/description/args_schema/run) returning
                     {"ok": bool, "output": str}; tools persist their raw results into a
                     per-task workspace directory.
  Mock tools         MockSearchTool / MockBrowseTool retrieve from kb.py (no network);
                     TerminalTool runs a whitelist of read-only shell commands
                     (grep/head/tail/cat/ls/wc/sed/sort/uniq) inside the task workspace,
                     exactly the "persist results, inspect with grep/head" pattern of the
                     BrowseComp harness in design doc section 4.2.
  Real adapters      TavilySearchTool / SearXNGSearchTool are TODO stubs only -- no
                     network code is written on this node.
  TrajectoryRecorder messages + tool calls are appended to <workspace>/trajectory.jsonl.
  Rollouts           run_mock_rollout: a scripted policy that walks the task's formal
                     expression through the mock tools (always succeeds by construction;
                     used to smoke-test the harness and to produce dry-run trajectories).
                     run_teacher_rollout: a real teacher-in-the-loop rollout (skippable,
                     never invoked under --no-teacher).

Usage (smoke test with a freshly generated task):
  python3 pipelines/deep_search/harness.py --demo --hops 3 --seed 3
  python3 pipelines/deep_search/harness.py --task-file tasks.jsonl --idx 0
"""
from __future__ import annotations

import argparse
import json
import random
import re
import shlex
import subprocess
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[2]))

from pipelines.common import teacher_client  # noqa: E402  (no network at import time)
from pipelines.deep_search import kb, task_gen  # noqa: E402

AGENT_SYSTEM = (
    "You are a deep-research agent. You have three tools:\n"
    '  search(query: str)          -> web search, returns ranked results\n'
    '  browse(url: str)            -> open a page and return its text\n'
    '  terminal(command: str)      -> read-only shell (grep/head/tail/cat/ls/wc/sed/sort/uniq)\n'
    "    over files saved in your per-task workspace (tool outputs persist there).\n"
    "To call a tool, output exactly one JSON line: {\"tool\": \"<name>\", \"args\": {...}}.\n"
    "When you are confident of the answer, finish with: {\"final_answer\": \"<exact name>\"}."
)

ALLOWED_CMDS = {"grep", "head", "tail", "cat", "ls", "wc", "sed", "sort", "uniq"}


# --------------------------------------------------------------------- tools

class Tool:
    name = "tool"
    description = ""
    args_schema: dict = {}

    def run(self, workspace: Path, **args) -> dict:  # pragma: no cover - abstract
        raise NotImplementedError


class MockSearchTool(Tool):
    name = "search"
    description = "Search the knowledge base by keywords; returns ranked entity hits."
    args_schema = {"query": "str"}

    def run(self, workspace: Path, query: str = "", **_) -> dict:
        terms = [t.lower() for t in re.findall(r"[A-Za-z0-9']+", query)]
        hits = []
        for e in kb.all_entities():
            d = kb.ENTITIES[e]
            hay = (e + " " + " ".join(f"{k} {v}" for k, v in d["attrs"].items())).lower()
            score = sum(hay.count(t) for t in terms)
            if score:
                hits.append((score, e))
        hits.sort(key=lambda x: (-x[0], x[1]))
        results = [{"title": e, "url": f"kb://{e.replace(' ', '_')}",
                    "snippet": kb.entity_card(e).splitlines()[1]} for _s, e in hits[:5]]
        _save(workspace, f"search_{_counter(workspace, 'search'):03d}.json",
              json.dumps({"query": query, "results": results}, ensure_ascii=False, indent=2))
        if not results:
            return {"ok": True, "output": "no results"}
        out = "\n".join(f"{i + 1}. {r['title']}  ({r['url']})  {r['snippet']}"
                        for i, r in enumerate(results))
        return {"ok": True, "output": out}


class MockBrowseTool(Tool):
    name = "browse"
    description = "Open a kb:// page and return its full text."
    args_schema = {"url": "str"}

    def run(self, workspace: Path, url: str = "", **_) -> dict:
        name = url.replace("kb://", "").replace("_", " ").strip()
        if name not in kb.ENTITIES:
            return {"ok": False, "output": f"page not found: {url}"}
        text = kb.entity_card(name)
        slug = re.sub(r"[^A-Za-z0-9]+", "_", name).strip("_")
        _save(workspace, f"page_{slug}.txt", text)
        return {"ok": True, "output": text[:6000]}


class TerminalTool(Tool):
    name = "terminal"
    description = "Run a read-only shell command inside the task workspace."
    args_schema = {"command": "str"}

    def run(self, workspace: Path, command: str = "", **_) -> dict:
        try:
            argv = shlex.split(command)
        except ValueError as e:
            return {"ok": False, "output": f"parse error: {e}"}
        if not argv or argv[0] not in ALLOWED_CMDS:
            return {"ok": False, "output": f"command not allowed: {argv[:1]}"}
        for tok in argv[1:]:
            p = (workspace / tok).resolve() if not tok.startswith("-") else workspace
            if not str(p).startswith(str(workspace.resolve())):
                return {"ok": False, "output": f"path escapes workspace: {tok}"}
        try:
            proc = subprocess.run(argv, cwd=workspace, capture_output=True, text=True, timeout=10)
        except Exception as e:  # noqa: BLE001
            return {"ok": False, "output": f"exec error: {e}"}
        out = (proc.stdout + proc.stderr).strip()[:4000]
        return {"ok": proc.returncode in (0, 1), "output": out or "(no output)"}


class TavilySearchTool(Tool):
    """TODO(design doc 4.4): real web search via the Tavily API.

    Not implemented on this node (no network, no API key). To implement: POST
    {"query": q, "max_results": 5} to https://api.tavily.com/search with header
    Authorization: Bearer ***REDACTED*** map results to the MockSearchTool output
    format ("title (url) snippet" lines) and persist raw JSON into the workspace.
    """
    name = "search"

    def run(self, workspace: Path, **args) -> dict:
        raise NotImplementedError("TODO: Tavily adapter (no network on this node)")


class SearXNGSearchTool(Tool):
    """TODO(design doc 4.4): self-hosted SearXNG + local index adapter.

    Not implemented. Point SEARXNG_BASE_URL at an internal instance, GET /search
    with format=json, and map results as in MockSearchTool.
    """
    name = "search"

    def run(self, workspace: Path, **args) -> dict:
        raise NotImplementedError("TODO: SearXNG adapter (no network on this node)")


def _counter(workspace: Path, prefix: str) -> int:
    return len(list(workspace.glob(f"{prefix}_*.json"))) + 1


def _save(workspace: Path, name: str, text: str) -> None:
    (workspace / name).write_text(text, encoding="utf-8")


# ------------------------------------------------------------- harness proper

class TrajectoryRecorder:
    def __init__(self, workspace: Path):
        self.path = workspace / "trajectory.jsonl"
        self.step = 0

    def log(self, record: dict) -> None:
        record = {"step": self.step, **record}
        with open(self.path, "a", encoding="utf-8") as f:
            f.write(json.dumps(record, ensure_ascii=False) + "\n")
        self.step += 1


class Harness:
    """Per-task workspace + tool execution + trajectory recording."""

    def __init__(self, task_id: str, workdir_root: str | Path, tools: list[Tool] | None = None):
        self.task_id = task_id
        self.workspace = Path(workdir_root) / task_id
        self.workspace.mkdir(parents=True, exist_ok=True)
        self.tools = {t.name: t for t in (tools or [MockSearchTool(), MockBrowseTool(), TerminalTool()])}
        self.recorder = TrajectoryRecorder(self.workspace)

    def execute(self, tool_name: str, args: dict) -> dict:
        tool = self.tools.get(tool_name)
        if tool is None:
            res = {"ok": False, "output": f"unknown tool: {tool_name}"}
        else:
            try:
                res = tool.run(self.workspace, **args)
            except Exception as e:  # noqa: BLE001
                res = {"ok": False, "output": f"tool error: {e}"}
        self.recorder.log({"role": "tool_call", "tool": tool_name, "args": args,
                           "ok": res["ok"]})
        return res


# ------------------------------------------------------------------ matching

def _norm(s: str) -> str:
    return re.sub(r"\s+", " ", s.strip().lower()).rstrip(".*")


def match_answer(prediction: str, gold: str) -> bool:
    """normalized_exact match used by reward.type=search_verify."""
    return _norm(prediction) == _norm(gold)


# ------------------------------------------------------------------- rollouts

def run_mock_rollout(task: dict, harness: Harness) -> dict:
    """Scripted policy: walk the formal expression through the mock tools.

    Deterministic; succeeds whenever the task's answer is unique (guaranteed by
    task_gen). Produces an assistant/tool message list suitable for SFT export.
    """
    messages: list[dict] = []
    browsed: set[str] = set()

    def say(text: str) -> None:
        messages.append({"role": "assistant", "content": text})
        harness.recorder.log({"role": "assistant", "content": text})

    def call(tool: str, args: dict) -> dict:
        res = harness.execute(tool, args)
        call_msg = f'{{"tool": "{tool}", "args": {json.dumps(args, ensure_ascii=False)}}}'
        messages.append({"role": "assistant", "content": call_msg})
        messages.append({"role": "tool",
                         "content": json.dumps({"tool": tool, "ok": res["ok"],
                                                "output": res["output"][:3000]},
                                               ensure_ascii=False)})
        return res

    def browse(entity: str) -> None:
        if entity not in browsed:
            browsed.add(entity)
            call("browse", {"url": f"kb://{entity.replace(' ', '_')}"})

    def solve(node) -> set[str]:
        op = node[0]
        if op == "E":
            say(f"I'll start by searching for \"{node[1]}\".")
            call("search", {"query": node[1]})
            browse(node[1])
            return {node[1]}
        if op in ("R", "RI"):
            sub = solve(node[2])
            rel = node[1]
            direction = "inverse" if op == "RI" else "forward"
            say(f"I follow the {direction} relation '{rel}' for: {', '.join(sorted(sub))}.")
            out: set[str] = set()
            for m in sorted(sub):
                browse(m)
                edges = kb.rels_of(m).get(rel, []) if op == "R" else kb.inv_rels_of(m).get(rel, [])
                out.update(edges)
            return out
        if op == "F":
            s = solve(node[1])
            attr, cop, val = node[2], node[3], node[4]
            say(f"I filter the {len(s)} candidate(s) on attribute '{attr}' {cop} {val!r}.")
            for m in sorted(s):
                browse(m)
            return {e for e in s if task_gen._cmp(kb.attrs_of(e).get(attr), cop, val)}
        if op == "NE":
            s = solve(node[1])
            say(f"I exclude {node[2]} from the candidates.")
            return s - {node[2]}
        raise ValueError(op)

    final = solve(task["expression"])
    say("I double-check the pages saved in my workspace.")
    call("terminal", {"command": f"grep -ril \"{task['answer'].split()[0]}\" ."})
    answer = task["answer"]
    success = final == {answer}
    final_msg = (f"Based on the gathered evidence, the answer is: {answer}.\n"
                 f'{{"final_answer": "{answer}"}}')
    say(final_msg)
    return {"success": success, "messages": messages, "solved_set": sorted(final)}


def run_teacher_rollout(task: dict, harness: Harness, max_steps: int = 30) -> dict:
    """Teacher-in-the-loop rollout. NEVER call under --no-teacher.

    Protocol: teacher replies either with a tool-call JSON line
    ({"tool": ..., "args": ...}) or with {"final_answer": "..."}.
    """
    messages: list[dict] = [
        {"role": "system", "content": AGENT_SYSTEM},
        {"role": "user", "content": task["question"]},
    ]
    for _step in range(max_steps):
        reply = teacher_client.chat(messages, max_tokens=4096)[0]
        messages.append({"role": "assistant", "content": reply})
        harness.recorder.log({"role": "assistant", "content": reply})
        try:
            start = reply.find("{")
            obj, _ = json.JSONDecoder().raw_decode(reply[start:])
        except Exception:  # noqa: BLE001
            messages.append({"role": "user", "content":
                             "Reply with a single JSON tool call or {\"final_answer\": ...}."})
            continue
        if "final_answer" in obj:
            pred = str(obj["final_answer"])
            return {"success": match_answer(pred, task["answer"]),
                    "messages": messages[2:], "prediction": pred}
        if "tool" in obj:
            res = harness.execute(str(obj["tool"]), dict(obj.get("args", {})))
            messages.append({"role": "tool", "content": json.dumps(
                {"tool": obj["tool"], "ok": res["ok"], "output": res["output"][:3000]},
                ensure_ascii=False)})
    return {"success": False, "messages": messages[2:], "prediction": None}


def main() -> None:
    ap = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    ap.add_argument("--demo", action="store_true", help="generate a task and run a mock rollout")
    ap.add_argument("--task-file", help="JSONL of tasks (from task_gen.py --out)")
    ap.add_argument("--idx", type=int, default=0)
    ap.add_argument("--hops", type=int, default=3)
    ap.add_argument("--seed", type=int, default=0)
    ap.add_argument("--workdir", default=str(Path(__file__).parent / "workdir"))
    ap.add_argument("--teacher", action="store_true",
                    help="also run a teacher rollout (requires a teacher service)")
    args = ap.parse_args()

    if args.task_file:
        tasks = [json.loads(l) for l in open(args.task_file, encoding="utf-8") if l.strip()]
        task = tasks[args.idx]
    else:
        rng = random.Random(args.seed)
        task = task_gen.generate_task(rng, args.hops)
        task["id"] = "demo-0001"
    print(f"task: hops={task['hops']} answer={task['answer']!r}")
    print(task["question"])

    harness = Harness(task.get("id", "demo-0001"), args.workdir)
    res = run_mock_rollout(task, harness)
    files = sorted(p.name for p in harness.workspace.iterdir())
    print(f"\nmock rollout: success={res['success']} steps={len(res['messages'])}")
    print(f"workspace {harness.workspace}: {files}")

    if args.teacher:
        res_t = run_teacher_rollout(task, harness)
        print(f"teacher rollout: success={res_t['success']} prediction={res_t.get('prediction')!r}")


if __name__ == "__main__":
    main()
