{"content": "#!/usr/bin/env python3
"""K3-style mock office applications (Pipeline E, design doc section 6.1).

In-memory minimal implementations of four services (plain python classes, no REST):
  MockGmail       send/list/read/search/reply/archive/delete/label + receive_email (event)
  MockCalendar    create/list/get/update/delete events + conflict check + invite (event)
  MockFileSystem  write/read/append/delete/move/list/exists
  MockSheets      create/set/get cells, append rows, sum/avg ranges, find rows

Every app:
  - persists state to JSON (save/load), so a multi-day scenario can be checkpointed;
  - supports EVENT INJECTION (inject_event): external world changes (incoming mail,
    meeting invites, files appearing, sheets being prefilled);
  - exposes a state-assertion API (check / run_assertions) used as the deterministic
    scoring rules of design doc section 6.2 ("每个事件携带确定性评分规则").

Usage (self-test: inject state -> operate -> assert):
  python3 pipelines/office/mock_apps.py
"""
from __future__ import annotations

import json
import re
from pathlib import Path
from typing import Any

DEFAULT_DATE = "2026-08-03"


def _eq(a: Any, b: Any) -> bool:
    if a == b:
        return True
    try:
        return float(a) == float(b)
    except (TypeError, ValueError):
        return str(a) == str(b)


# --------------------------------------------------------------------- gmail

class MockGmail:
    name = "gmail"

    def __init__(self) -> None:
        self.state: dict = {"next_id": 1, "emails": [], "labels": []}

    # -- state persistence
    def save(self, directory: str | Path) -> Path:
        p = Path(directory) / f"{self.name}.json"
        p.write_text(json.dumps(self.state, ensure_ascii=False, indent=2), encoding="utf-8")
        return p

    @classmethod
    def load(cls, directory: str | Path) -> "MockGmail":
        app = cls()
        app.state = json.loads((Path(directory) / f"{cls.name}.json").read_text(encoding="utf-8"))
        return app

    # -- helpers
    def _get(self, email_id: int) -> dict:
        for e in self.state["emails"]:
            if e["id"] == email_id:
                return e
        raise KeyError(f"no email with id {email_id}")

    def _add(self, **kw) -> int:
        e = {"id": self.state["next_id"], "folder": "inbox", "cc": None,
             "labels": [], "read": False, "date": DEFAULT_DATE, **kw}
        self.state["next_id"] += 1
        self.state["emails"].append(e)
        return e["id"]

    # -- agent-facing methods
    def send_email(self, to: str, subject: str, body: str, cc: str | None = None,
                   date: str = DEFAULT_DATE) -> int:
        return self._add(folder="sent", **{"from": "me@acme.example"}, to=to,
                         subject=subject, body=body, cc=cc, date=date, read=True)

    def receive_email(self, from_: str, subject: str, body: str,
                      date: str = DEFAULT_DATE) -> int:
        """Event injection: an external email arrives in the inbox."""
        return self._add(**{"from": from_}, to="me@acme.example",
                         subject=subject, body=body, date=date)

    def list_inbox(self, folder: str = "inbox") -> list[dict]:
        return [{"id": e["id"], "from": e["from"], "subject": e["subject"],
                 "date": e["date"], "read": e["read"]}
                for e in self.state["emails"] if e["folder"] == folder]

    def read_email(self, email_id: int) -> dict:
        e = self._get(email_id)
        e["read"] = True
        return dict(e)

    def search_emails(self, query: str | None = None, from_: str | None = None,
                      subject_contains: str | None = None,
                      folder: str | None = None) -> list[int]:
        out = []
        for e in self.state["emails"]:
            if folder and e["folder"] != folder:
                continue
            if from_ and e["from"] != from_:
                continue
            if subject_contains and subject_contains.lower() not in e["subject"].lower():
                continue
            if query and query.lower() not in (e["subject"] + " " + e["body"]).lower():
                continue
            out.append(e["id"])
        return out

    def reply_email(self, email_id: int, body: str, date: str = DEFAULT_DATE) -> int:
        orig = self._get(email_id)
        return self.send_email(to=orig["from"], subject=f"Re: {orig['subject']}",
                               body=body, date=date)

    def archive_email(self, email_id: int) -> None:
        self._get(email_id)["folder"] = "archive"

    def delete_email(self, email_id: int) -> None:
        self._get(email_id)["folder"] = "trash"

    def add_label(self, email_id: int, label: str) -> None:
        e = self._get(email_id)
        if label not in e["labels"]:
            e["labels"].append(label)
        if label not in self.state["labels"]:
            self.state["labels"].append(label)

    # -- assertions
    def check(self, name: str, args: dict) -> tuple[bool, str]:
        if name == "email_sent":
            for e in self.state["emails"]:
                if e["folder"] != "sent" or e["to"] != args["to"]:
                    continue
                if args.get("subject_contains") and args["subject_contains"].lower() not in e["subject"].lower():
                    continue
                if args.get("body_contains") and args["body_contains"] not in e["body"]:
                    continue
                return True, f"sent email id={e['id']} matches"
            return False, f"no sent email to {args['to']} matching {args}"
        if name == "email_received":
            return (any(e["folder"] == "inbox" and e["from"] == args["from_"]
                        and (not args.get("subject_contains")
                             or args["subject_contains"].lower() in e["subject"].lower())
                        for e in self.state["emails"]),
                    f"inbox from {args.get('from_')}")
        if name == "inbox_empty":
            n = len(self.list_inbox())
            return n == 0, f"inbox has {n} emails"
        return False, f"unknown gmail check {name!r}"


# ------------------------------------------------------------------ calendar

class MockCalendar:
    name = "calendar"

    def __init__(self) -> None:
        self.state: dict = {"next_id": 1, "events": []}

    def save(self, directory: str | Path) -> Path:
        p = Path(directory) / f"{self.name}.json"
        p.write_text(json.dumps(self.state, ensure_ascii=False, indent=2), encoding="utf-8")
        return p

    @classmethod
    def load(cls, directory: str | Path) -> "MockCalendar":
        app = cls()
        app.state = json.loads((Path(directory) / f"{cls.name}.json").read_text(encoding="utf-8"))
        return app

    def _get(self, event_id: int) -> dict:
        for e in self.state["events"]:
            if e["id"] == event_id:
                return e
        raise KeyError(f"no event with id {event_id}")

    def create_event(self, title: str, date: str, start: str, end: str,
                     attendees: list[str] | None = None, location: str | None = None,
                     notes: str | None = None) -> int:
        e = {"id": self.state["next_id"], "title": title, "date": date, "start": start,
             "end": end, "attendees": attendees or [], "location": location,
             "notes": notes, "kind": "event"}
        self.state["next_id"] += 1
        self.state["events"].append(e)
        return e["id"]

    def receive_invite(self, title: str, date: str, start: str, end: str,
                       organizer: str, **kw) -> int:
        """Event injection: an external meeting invite lands on the calendar."""
        eid = self.create_event(title, date, start, end, **kw)
        self._get(eid)["kind"] = "invite"
        self._get(eid)["organizer"] = organizer
        return eid

    def list_events(self, date: str | None = None) -> list[dict]:
        evs = [e for e in self.state["events"] if date is None or e["date"] == date]
        return sorted((dict(e) for e in evs), key=lambda e: (e["date"], e["start"]))

    def get_event(self, event_id: int) -> dict:
        return dict(self._get(event_id))

    def update_event(self, event_id: int, **fields) -> None:
        self._get(event_id).update(fields)

    def delete_event(self, event_id: int) -> None:
        self.state["events"] = [e for e in self.state["events"] if e["id"] != event_id]

    def events_on_date(self, date: str) -> list[dict]:
        return self.list_events(date)

    def find_conflicts(self, date: str, start: str, end: str) -> list[dict]:
        return [e for e in self.state["events"]
                if e["date"] == date and e["start"] < end and start < e["end"]]

    def check(self, name: str, args: dict) -> tuple[bool, str]:
        if name == "event_exists":
            for e in self.state["events"]:
                if args.get("title_contains") and args["title_contains"].lower() not in e["title"].lower():
                    continue
                if args.get("date") and e["date"] != args["date"]:
                    continue
                if args.get("start") and e["start"] != args["start"]:
                    continue
                return True, f"event id={e['id']} matches"
            return False, f"no event matching {args}"
        if name == "no_conflicts_on":
            date = args["date"]
            evs = sorted((e for e in self.state["events"] if e["date"] == date),
                         key=lambda e: e["start"])
            for a, b in zip(evs, evs[1:]):
                if a["end"] > b["start"]:
                    return False, f"conflict: {a['title']!r} overlaps {b['title']!r}"
            return True, f"{len(evs)} events on {date}, no overlaps"
        return False, f"unknown calendar check {name!r}"


# -------------------------------------------------------------- file system

class MockFileSystem:
    name = "fs"

    def __init__(self) -> None:
        self.state: dict = {"files": {}}

    def save(self, directory: str | Path) -> Path:
        p = Path(directory) / f"{self.name}.json"
        p.write_text(json.dumps(self.state, ensure_ascii=False, indent=2), encoding="utf-8")
        return p

    @classmethod
    def load(cls, directory: str | Path) -> "MockFileSystem":
        app = cls()
        app.state = json.loads((Path(directory) / f"{cls.name}.json").read_text(encoding="utf-8"))
        return app

    def write_file(self, path: str, content: str) -> None:
        self.state["files"][path] = content

    def read_file(self, path: str) -> str:
        if path not in self.state["files"]:
            raise KeyError(f"no file {path}")
        return self.state["files"][path]

    def append_file(self, path: str, content: str) -> None:
        self.state["files"][path] = self.state["files"].get(path, "") + content

    def delete_file(self, path: str) -> None:
        self.state["files"].pop(path, None)

    def move_file(self, src: str, dst: str) -> None:
        if src not in self.state["files"]:
            raise KeyError(f"no file {src}")
        self.state["files"][dst] = self.state["files"].pop(src)

    def list_dir(self, prefix: str = "/") -> list[str]:
        return sorted(p for p in self.state["files"] if p.startswith(prefix))

    def exists(self, path: str) -> bool:
        return path in self.state["files"]

    def check(self, name: str, args: dict) -> tuple[bool, str]:
        if name == "file_exists":
            ok = args["path"] in self.state["files"]
            return ok, f"file {args['path']} {'exists' if ok else 'missing'}"
        if name == "file_contains":
            content = self.state["files"].get(args["path"])
            if content is None:
                return False, f"file {args['path']} missing"
            ok = args["text"] in content
            return ok, (f"{args['text']!r} {'found' if ok else 'NOT found'} in {args['path']}")
        return False, f"unknown fs check {name!r}"


# --------------------------------------------------------------------- sheets

_CELL_RE = re.compile(r"^([A-Z]+)(\d+)$")


def _col_to_idx(col: str) -> int:
    idx = 0
    for ch in col:
        idx = idx * 26 + (ord(ch) - 64)
    return idx


def _idx_to_col(i: int) -> str:
    s = ""
    while i:
        i, r = divmod(i - 1, 26)
        s = chr(65 + r) + s
    return s


def _iter_range(cell_range: str) -> list[str]:
    a, b = cell_range.split(":")
    m1, m2 = _CELL_RE.match(a), _CELL_RE.match(b)
    if not (m1 and m2):
        raise ValueError(f"bad range {cell_range!r}")
    c1, r1 = _col_to_idx(m1.group(1)), int(m1.group(2))
    c2, r2 = _col_to_idx(m2.group(1)), int(m2.group(2))
    return [f"{_idx_to_col(c)}{r}" for c in range(min(c1, c2), max(c1, c2) + 1)
            for r in range(min(r1, r2), max(r1, r2) + 1)]


class MockSheets:
    name = "sheets"

    def __init__(self) -> None:
        self.state: dict = {"sheets": {}}

    def save(self, directory: str | Path) -> Path:
        p = Path(directory) / f"{self.name}.json"
        p.write_text(json.dumps(self.state, ensure_ascii=False, indent=2), encoding="utf-8")
        return p

    @classmethod
    def load(cls, directory: str | Path) -> "MockSheets":
        app = cls()
        app.state = json.loads((Path(directory) / f"{cls.name}.json").read_text(encoding="utf-8"))
        return app

    def _sheet(self, name: str) -> dict:
        if name not in self.state["sheets"]:
            raise KeyError(f"no sheet {name!r}")
        return self.state["sheets"][name]

    def create_sheet(self, name: str) -> None:
        self.state["sheets"].setdefault(name, {})

    def create_with_data(self, name: str, rows: list[list]) -> None:
        """Event injection / setup: a prefilled sheet appears."""
        self.create_sheet(name)
        for r, row in enumerate(rows, start=1):
            for c, val in enumerate(row, start=1):
                self.set_cell(name, f"{_idx_to_col(c)}{r}", val)

    def set_cell(self, sheet: str, cell: str, value) -> None:
        self._sheet(sheet)[cell] = value

    def get_cell(self, sheet: str, cell: str):
        return self._sheet(sheet).get(cell)

    def append_row(self, sheet: str, values: list) -> int:
        cells = self._sheet(sheet)
        max_row = max((int(_CELL_RE.match(c).group(2)) for c in cells), default=0)
        row = max_row + 1
        for c, val in enumerate(values, start=1):
            cells[f"{_idx_to_col(c)}{row}"] = val
        return row

    def sum_range(self, sheet: str, cell_range: str):
        vals = [self._sheet(sheet).get(c, 0) for c in _iter_range(cell_range)]
        total = sum(float(v) for v in vals)
        return int(total) if total.is_integer() else round(total, 2)

    def avg_range(self, sheet: str, cell_range: str):
        cells = _iter_range(cell_range)
        vals = [float(self._sheet(sheet).get(c, 0)) for c in cells]
        return round(sum(vals) / len(vals), 2) if cells else 0

    def list_sheets(self) -> list[str]:
        return sorted(self.state["sheets"])

    def find_rows(self, sheet: str, col: str, value) -> list[int]:
        return sorted(int(_CELL_RE.match(c).group(2))
                      for c, v in self._sheet(sheet).items()
                      if c.startswith(col) and _eq(v, value))

    def check(self, name: str, args: dict) -> tuple[bool, str]:
        if name == "sheet_exists":
            ok = args["name"] in self.state["sheets"]
            return ok, f"sheet {args['name']} {'exists' if ok else 'missing'}"
        if name == "cell_equals":
            got = self._sheet(args["sheet"]).get(args["cell"])
            ok = got is not None and _eq(got, args["value"])
            return ok, f"{args['sheet']}!{args['cell']} = {got!r} (want {args['value']!r})"
        if name == "cell_contains":
            got = self._sheet(args["sheet"]).get(args["cell"])
            ok = got is not None and args["text"] in str(got)
            return ok, f"{args['sheet']}!{args['cell']} = {got!r}"
        return False, f"unknown sheets check {name!r}"


# ------------------------------------------------- event injection & assertions

def default_apps() -> dict[str, Any]:
    return {"gmail": MockGmail(), "calendar": MockCalendar(),
            "fs": MockFileSystem(), "sheets": MockSheets()}


def inject_event(apps: dict[str, Any], event: dict) -> Any:
    """Apply one external event, e.g.
    {"app": "gmail", "op": "receive_email", "args": {...}}."""
    app = apps[event["app"]]
    return getattr(app, event["op"])(**event.get("args", {}))


def run_assertions(apps: dict[str, Any], assertions: list[dict]) -> list[dict]:
    """Run programmatic state assertions (deterministic scoring rules)."""
    results = []
    for a in assertions:
        try:
            ok, detail = apps[a["app"]].check(a["check"], a.get("args", {}))
        except Exception as e:  # noqa: BLE001
            ok, detail = False, f"assertion error: {e}"
        results.append({"assertion": a, "ok": ok, "detail": detail})
    return results


def _self_test() -> None:
    apps = default_apps()
    inject_event(apps, {"app": "gmail", "op": "receive_email",
                        "args": {"from_": "boss@acme.example", "subject": "Report",
                                 "body": "Send me the report."}})
    inject_event(apps, {"app": "calendar", "op": "receive_invite",
                        "args": {"title": "Kickoff", "date": "2026-08-04", "start": "10:00",
                                 "end": "11:00", "organizer": "pm@acme.example"}})
    inject_event(apps, {"app": "sheets", "op": "create_with_data",
                        "args": {"name": "T", "rows": [["item", "n"], ["a", 3], ["b", 4]]}})
    inject_event(apps, {"app": "fs", "op": "write_file",
                        "args": {"path": "/in/x.txt", "content": "hello"}})
    # operate
    rid = apps["gmail"].reply_email(1, "On it.")
    apps["fs"].move_file("/in/x.txt", "/out/x.txt")
    assert apps["sheets"].sum_range("T", "B2:B3") == 7
    apps["sheets"].set_cell("T", "B4", 7)
    apps["calendar"].create_event("Focus time", "2026-08-04", "13:00", "14:00")
    # persist & reload
    tmp = Path("/tmp/mock_apps_selftest")
    tmp.mkdir(exist_ok=True)
    for app in apps.values():
        app.save(tmp)
    reloaded = MockGmail.load(tmp)
    assert reloaded.read_email(rid)["to"] == "boss@acme.example"
    # assert
    res = run_assertions(apps, [
        {"app": "gmail", "check": "email_sent", "args": {"to": "boss@acme.example", "body_contains": "On it"}},
        {"app": "calendar", "check": "event_exists", "args": {"title_contains": "Focus", "date": "2026-08-04", "start": "13:00"}},
        {"app": "calendar", "check": "no_conflicts_on", "args": {"date": "2026-08-04"}},
        {"app": "fs", "check": "file_contains", "args": {"path": "/out/x.txt", "text": "hello"}},
        {"app": "sheets", "check": "cell_equals", "args": {"sheet": "T", "cell": "B4", "value": 7}},
    ])
    for r in res:
        print(("PASS" if r["ok"] else "FAIL"), "-", r["detail"])
    assert all(r["ok"] for r in res), "self-test failed"
    print("mock_apps self-test: all assertions passed")


if __name__ == "__main__":
    _self_test()
